SELECT 
  FROM oa_iam.access_request q
  LEFT JOIN oa_iam.role r ON r.id = q.role_id
 WHERE q.tenant_id = #{tenantId}
   AND q.requester_user_id = #{requesterUserId}
   AND q.request_type = #{requestType}
   AND q.role_id = #{roleId}
   AND q.status = 'PENDING'
 ORDER BY q.id DESC
 LIMIT 1

SELECT 
  FROM oa_iam.access_request q
  LEFT JOIN oa_iam.role r ON r.id = q.role_id
 WHERE q.tenant_id = #{tenantId}

   AND q.requester_user_id = #{requesterUserId}


   AND q.status = #{status}


   AND q.id > #{cursor}

 ORDER BY q.id
 LIMIT #{limit}
